const beforePlatformStatus=render;
render=function(){
 if(location.hash!=='#platform-status')return beforePlatformStatus();
 document.getElementById('app').innerHTML=integratedShell('platform-status',heading('Platform capability review','Local pilot · Powered by Scholarion')+'<p id="platform-message" role="status">Loading verified implementation inventory…</p><div id="platform-content"></div>',model.role);bind();normalizeWorkspace();loadPlatformStatus();
};
async function loadPlatformStatus(){try{
 workspaceSession=await workspaceApi('session');if(!workspaceSession.courses.includes(selectedCourse))selectedCourse=workspaceSession.courses[0]||'';
 const d=await workspaceApi('platform/status');if(location.hash!=='#platform-status')return;normalizeWorkspace();
 document.getElementById('platform-message').textContent='Local implementation inventory. Production is blocked. LIVE means a local workflow, not production readiness.';
 document.getElementById('platform-content').innerHTML=`<section class="card prose"><h2>Capability status board</h2><p>${esc(d.brandDecision)}</p><dl>${Object.entries(d.definitions).map(([k,v])=>`<dt><strong>${esc(k)}</strong></dt><dd>${esc(v)}</dd>`).join('')}</dl><div style="overflow:auto"><table><caption>Implemented scope and remaining blockers</caption><thead><tr><th>Capability</th><th>Status</th><th>Evidence and limitations</th></tr></thead><tbody>${d.capabilities.map(c=>`<tr><th scope="row">${esc(c.name)}</th><td>${esc(c.status)}</td><td>${esc(c.limits)} ${c.route.endsWith('.py')?'':`<a href="#${esc(c.route)}">Open</a>`}</td></tr>`).join('')}</tbody></table></div></section><section class="card prose"><h2>Latest successful local recovery drill</h2><p>${esc(d.recovery?.status||"NOT RUN")} � ${esc(d.recovery?.checkedAt?new Date(d.recovery.checkedAt*1000).toLocaleString():"No completed drill")}</p><p>${esc(d.recovery?.limits||"An operator must run a snapshot and isolated restore drill. No live database is replaced.")}</p><h2>Master specification acceptance</h2><ol>${d.acceptance.map(a=>`<li><strong>${esc(a.status)}</strong> — ${esc(a.reason)}</li>`).join('')}</ol><button class="button secondary" id="platform-export">Download status report</button></section>${workspaceSession.role==='instructor'?`<section class="card prose"><h2>Catalog claims review</h2><p>Reviews draft copy for restricted claim language. Publication is disabled. No claim becomes verified merely by passing this phrase check.</p><form id="catalog-claims-form"><label>Course<select name="course">${workspaceSession.courses.map(c=>`<option>${esc(c)}</option>`).join('')}</select></label><label>Product title<input name="title" required maxlength="200"></label><label>Draft description<textarea name="body" required maxlength="8000"></textarea></label><button class="button">Review and save draft</button></form><p id="claims-message" role="status"></p></section>`:''}`;
 document.getElementById('platform-export').onclick=()=>download('scholarion-capability-status.json',JSON.stringify(d,null,2),'application/json');
 }catch(e){if(location.hash==='#platform-status')document.getElementById('platform-message').textContent=e.message+' — Connect using Workspace account.';}}
document.addEventListener('submit',async e=>{if(e.target.id!=='catalog-claims-form')return;e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const r=await workspaceApi('catalog-review/review',Object.fromEntries(new FormData(e.target)));document.getElementById('claims-message').textContent=r.status+'. '+(r.findings.length?'Restricted wording: '+r.findings.join(', ')+'. ':'')+r.note+' Saved review: '+r.id;}catch(err){document.getElementById('claims-message').textContent=err.message;}finally{b.disabled=false;}});
render();
